session_start(); include('check-login.php'); include_once('club-utils.php'); club_ensure_tables($con); if(!club_is_admin()){http_response_code(403);exit('Administrators only.');}$uid=$_SESSION['USERID'];$msg='';
if(isset($_POST['create'])){$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$leader=trim($_POST['leader']??'');if($name===''||$leader==='')$msg='Give the club a name and choose a student leader.';else{$id=club_id();$n=mysqli_real_escape_string($con,substr($name,0,100));$d=mysqli_real_escape_string($con,substr($desc,0,3000));$l=mysqli_real_escape_string($con,$leader);$a=mysqli_real_escape_string($con,$uid);mysqli_query($con,"INSERT INTO tblclub(clubid,clubname,description,leaderid,createdby,createdat) VALUES('$id','$n','$d','$l','$a',NOW())");$mid=club_id('MBR');mysqli_query($con,"INSERT INTO tblclubmember(memberid,clubid,userid,role,status,addedby,joinedat) VALUES('$mid','$id','$l','leader','active','$a',NOW())");club_log($con,$id,$leader,$uid,'created club and appointed leader',$name);$msg='Club created and leader appointed.';}}
$students=mysqli_query($con,"SELECT userid,CONCAT_WS(' ',firstname,othernames,surname) name FROM tblsystemuser WHERE systemtype='Student' AND COALESCE(status,'active')<>'block' ORDER BY firstname,surname");$clubs=mysqli_query($con,"SELECT c.*,CONCAT_WS(' ',u.firstname,u.othernames,u.surname) leadername,(SELECT COUNT(*) FROM tblclubmember m WHERE m.clubid=c.clubid AND m.status='active') members FROM tblclub c LEFT JOIN tblsystemuser u ON u.userid=c.leaderid ORDER BY c.createdat DESC");
?><!doctype html><html><head><?php include('links.php');?><link rel="stylesheet" href="css/clubs.css"></head><body class="clubs-page club-admin-page"><div class="header"><?php include('menu.php');?></div><main class="clubs-wrap"><section class="clubs-hero"><span>ADMIN CONTROL ROOM</span><h1>Clubs &amp; Societies</h1><p>Create communities, appoint student leaders, and supervise activity without taking over their space.</p></section><?php if($msg){?><div class="clubs-msg"><?php echo club_esc($msg);?></div><?php }?><section class="admin-create"><h2>Launch a new club</h2><form method="post"><input name="name" maxlength="100" required placeholder="Club or society name"><textarea name="description" maxlength="3000" placeholder="What is this club about?"></textarea><select name="leader" required><option value="">Choose the student leader</option><?php while($s=mysqli_fetch_assoc($students)){?><option value="<?php echo club_esc($s['userid']);?>"><?php echo club_esc(trim($s['name'])?:$s['userid']);?></option><?php }?></select><button class="club-btn" name="create">Create club <i class="fa fa-rocket"></i></button></form></section><section class="club-grid"><?php while($c=mysqli_fetch_assoc($clubs)){?><article class="club-card"><div class="club-card__spark">✦</div><h2><?php echo club_esc($c['clubname']);?></h2><p><?php echo club_esc($c['description']);?></p><div class="club-meta"><span><?php echo (int)$c['members'];?> members</span><span>Leader: <?php echo club_esc(trim($c['leadername'])?:$c['leaderid']);?></span></div><a class="club-btn" href="club-room.php?club=<?php echo rawurlencode($c['clubid']);?>">Audit room <i class="fa fa-eye"></i></a></article><?php }?></section></main></body></html>
